package com.smartsociety.platform.complaint;import com.smartsociety.platform.common.Enums.ComplaintStatus;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;public class ComplaintLifecycleTest{@Test void onlyForwardTransitionsAreAllowed(){assertTrue(valid(ComplaintStatus.OPEN,ComplaintStatus.IN_PROGRESS));assertTrue(valid(ComplaintStatus.IN_PROGRESS,ComplaintStatus.RESOLVED));assertFalse(valid(ComplaintStatus.OPEN,ComplaintStatus.RESOLVED));assertFalse(valid(ComplaintStatus.RESOLVED,ComplaintStatus.OPEN));}private boolean valid(ComplaintStatus a,ComplaintStatus b){return(a==ComplaintStatus.OPEN&&b==ComplaintStatus.IN_PROGRESS)||(a==ComplaintStatus.IN_PROGRESS&&b==ComplaintStatus.RESOLVED);}}